"use strict";(globalThis.webpackChunkknowledge_core=globalThis.webpackChunkknowledge_core||[]).push([[5398],{3256(e){e.exports=JSON.parse('{"tag":{"label":"Grammar","permalink":"/knowledge-core/es/docs/tags/grammar","description":"Grammar rules and structures.","allTagsPath":"/knowledge-core/es/docs/tags","count":17,"items":[{"id":"gofluence-handbook/grammar/causatives","title":"Causatives","description":"Use have, get, make and let to say that someone or something causes another person or thing to act.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/causatives"},{"id":"gofluence-handbook/cheat-sheet","title":"Cheat Sheet","description":"One-page quick review of the key grammar, modals and phrases from the GoFluence classes.","permalink":"/knowledge-core/es/docs/gofluence-handbook/cheat-sheet"},{"id":"gofluence-handbook/common-mistakes","title":"Common Mistakes for Spanish Speakers","description":"Frequent English errors made by Spanish speakers at B1-B2 level, with corrections and explanations.","permalink":"/knowledge-core/es/docs/gofluence-handbook/common-mistakes"},{"id":"gofluence-handbook/vocabulary/describing-spaces","title":"Describing spaces","description":"Describe rooms, offices and workstations with this is / these are, there is / there are, prepositions of place and adjectives.","permalink":"/knowledge-core/es/docs/gofluence-handbook/vocabulary/describing-spaces"},{"id":"gofluence-handbook/grammar/expressing-possibility","title":"Expressing possibility","description":"Say that something is possible using can, could, may, might and adverbs such as maybe, perhaps and possibly.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/expressing-possibility"},{"id":"gofluence-handbook/grammar/expressing-probability","title":"Expressing probability","description":"Show how sure you are about the past and present with must, may, might, could and can\'t.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/expressing-probability"},{"id":"gofluence-handbook/grammar/first-conditional","title":"First conditional","description":"Talk about possible future actions and their likely results, discuss business options and make suggestions at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/first-conditional"},{"id":"gofluence-handbook/grammar/general-modal-rules","title":"General modal rules","description":"Learn the five basic rules for modal verbs such as can, must, will, should and might.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/general-modal-rules"},{"id":"gofluence-handbook/grammar/making-comparisons","title":"Making comparisons","description":"Compare people, tools, options and results at work with comparative adjectives and as ... as.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/making-comparisons"},{"id":"gofluence-handbook/grammar/making-deductions","title":"Making deductions","description":"Use clues to work out what is probably true or what the problem is, with must, might, could and can\'t.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/making-deductions"},{"id":"gofluence-handbook/grammar/making-predictions","title":"Making predictions","description":"Say what you think will happen at work, with the right level of certainty, using will, may, might and could.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/making-predictions"},{"id":"gofluence-handbook/projects-presentations/manage-scope-creep","title":"Manage scope creep","description":"Use infinitives of purpose (to, so as to, in order to, not to) to set goals and communicate limits and avoid scope creep.","permalink":"/knowledge-core/es/docs/gofluence-handbook/projects-presentations/manage-scope-creep"},{"id":"gofluence-handbook/grammar/must","title":"Must","description":"Use must to express obligation and to make confident guesses about people and situations at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/must"},{"id":"gofluence-handbook/grammar/object-and-subject-pronouns","title":"Object and subject pronouns","description":"Choose the right subject, object and possessive pronouns to avoid repeating names in emails, meetings and messages.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/object-and-subject-pronouns"},{"id":"gofluence-handbook/grammar/prepositions-of-position","title":"Prepositions of position","description":"Describe where people, things and files are, using inside, outside, above, below, next to, between and more.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/prepositions-of-position"},{"id":"gofluence-handbook/grammar/present-perfect-vs-simple-past","title":"Present perfect vs. simple past","description":"Choose between the present perfect and the simple past to talk about experience, finished actions and results that matter now.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/present-perfect-vs-simple-past"},{"id":"gofluence-handbook/grammar/zero-conditional","title":"Zero conditional","description":"Use the zero conditional to describe routines, rules and things that always happen at work.","permalink":"/knowledge-core/es/docs/gofluence-handbook/grammar/zero-conditional"}],"unlisted":false}}')}}]);